def transform(wb):
    ws = wb['Sheet2']
    bad_values = ('-', '0', '$', '$0', '$0.0')
    last_row = ws.max_row
    if last_row > 54:
        last_row = 54
    for row in range(last_row, 1, -1):
        j = ws.cell(row=row, column=10).value
        k = ws.cell(row=row, column=11).value
        j_bad = False
        if j is None:
            j_bad = True
        else:
            j_text = str(j).strip()
            if j_text == '' or j_text in bad_values:
                j_bad = True
            elif j == 0:
                j_bad = True
        k_bad = False
        if k is None:
            k_bad = True
        else:
            k_text = str(k).strip()
            if k_text == '' or k_text in bad_values:
                k_bad = True
            elif k == 0:
                k_bad = True
        if j_bad and k_bad:
            ws.delete_rows(row, 1)
    return None
